import{z as A,x as B,o as i,c as d,q as s,j as l,D as r,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"基数树","description":"","frontmatter":{"title":"基数树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/radix-tree.md","filePath":"cs/radix-tree.md","lastUpdated":1791413859000}'),p={name:"cs/radix-tree.md"};function m(D,a,c,h,T,C){const E=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=s('<h1 id="基数树" tabindex="-1">基数树 <a class="header-anchor" href="#基数树" aria-label="Permalink to &quot;基数树&quot;">​</a></h1><div class="epigraph"><p>单孩子的路径不必每个字符一个节点：把边标成一段串，节点数跟相异前缀走，不跟键长总和走。</p><footer>—— 据 Morrison, PATRICIA — Practical Algorithm To Retrieve Information Coded in Alphanumeric, JACM 1968；Fredkin, Trie Memory, CACM 1960 对照</footer></div><p><a href="/cs/trie">上一课</a>按字符下降、点名 Patricia/radix 压缩单孩子路径却不展开。本课不重讲结束标记。缺口是压缩：边标签是非空串（或一串二进制位），内部节点至少两个孩子（Patricia 常如此），查找时沿边比较整段。并查集下一课换合同；本课仍是串键字典。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Trie 最坏节点数 \\(\\Theta(\\sum L_i)\\)：一条长键、没有共享前缀时，链上每个字符一个节点，指针与 cache 行都浪费。缺口不是换字母表，而是<strong>把无分支路径收成一条边</strong>。插入若在边中间分叉，把边劈开，新内部节点挂两个孩子。</p><p><span class="marginnote">「压缩」翻译过来就是：凡是只有一条路的路段，不逐字符建节点，而是把整段字符写在边的标签上；节点只出现在分叉处和终点，数量由相异前缀的段数决定，不再跟键长总和走。</span></p><p>二进制 PATRICIA 按比特跳过「与兄弟相同的前缀」，跳过的位数存在节点里。字节 radix 树按字符块，思想相同。</p><p><span class="marginnote">Linux radix tree、路由表、内核页 cache 常用这一族。本课只交结构，不写内核 API。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找键 \\(s\\)：从根比较当前边标签与 \\(s\\) 的剩余前缀，全匹配则沿边走，失配则失败；到节点看结束位。插入：失配在边中则分裂该边。删除：若剩单孩子，可把边再合并回去，保持压缩。</p>',10)),(i(),l(o,null,{default:r(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%22%5D%20--%3E%20AB%5B%22%E8%BE%B9%20'ab'%22%5D%0A%20%20AB%20--%3E%20N%5B%22%E5%86%85%E9%83%A8%E8%8A%82%E7%82%B9%22%5D%0A%20%20N%20--%3E%20C%5B%22%E8%BE%B9%20'c'%20%E7%BB%93%E6%9D%9F%22%5D%0A%20%20N%20--%3E%20D%5B%22%E8%BE%B9%20'd'%20%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 BST：比较的是键的数字/字符结构，不是全键序比较一次（虽中序仍可能有序，若字母序）。与散列：支持最长前缀匹配——路由课会用，本课只承认结构能做。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"空间接近「相异前缀的段数」。查找步数 \\(\\Theta(L)\\) 符号比较仍在，但指针追逐次数变成 \\(\\Theta(\\)分叉点\\()\\)，对 cache 更友好。扇出实现仍可数组/哈希，与 Trie 课相同。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"代入一个数：字宽 \\(w=32\\) 的整数键走二进制 Patricia，表里已有 100 个键还是 1 亿个键，查找至多沿 32 个比特位下降——步数与键数无关，只与键长有关，这正是数字查找树相对比较树的合同。")],-1)),(i(),l(o,null,{default:r(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%96%B0%E9%94%AE%22%5D%20--%3E%20WALK%5B%22%E6%B2%BF%E7%8E%B0%E6%9C%89%E8%BE%B9%E6%A0%87%E7%AD%BE%E5%8C%B9%E9%85%8D%E5%89%8D%E7%BC%80%22%5D%0A%20%20WALK%20--%3E%20Q%7B%22%E5%89%8D%E7%BC%80%E5%9C%A8%E8%BE%B9%E4%B8%AD%E9%80%94%E5%A4%B1%E9%85%8D%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20SPLIT%5B%22%E5%9C%A8%E5%A4%B1%E9%85%8D%E5%A4%84%E5%8A%88%E8%BE%B9%3A%20%E6%96%B0%E5%86%85%E9%83%A8%E8%8A%82%E7%82%B9%E6%8E%A5%E7%AE%A1%E4%B8%A4%E6%AE%B5%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20ADD%5B%22%E8%A1%A5%E7%BB%93%E6%9D%9F%E4%BD%8D%E6%88%96%E6%8C%82%E6%96%B0%E8%BE%B9%22%5D%0A%20%20SPLIT%20--%3E%20OK%5B%22%E6%97%A0%E5%88%86%E6%94%AF%E8%B7%AF%E5%BE%84%E4%BB%8D%E8%A2%AB%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20ADD%20--%3E%20OK%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">劈边像在独木桥中间立一个新岔路口：桥被锯成两段，各挂回新路口两侧，原来走过的路一步都没变长；此后若有第三条路要汇入，也从新路口分出去。</span></p><p>键是整数时，按比特的 Patricia 给出 \\(\\Theta(w)\\) 最坏，\\(w\\) 为字宽，与 \\(n\\) 无关——这是数字查找树相对比较树的合同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把后缀树、后缀数组写进来，不把 AC 自动机当主干。也不进入大模型词表。并查集的键是元素编号、合同是分区，下一课不再沿符号下降。</p><p>后课默认：长键、稀疏前缀用压缩基数树。不相交集合的合并查找是另一 ADT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基数/Patricia：压缩无分支路径，分裂边上插入。</li><li>指针次数跟分叉走；最长前缀自然。</li><li>分区 ADT 是下一课并查集，不保管串。</li><li>出处：Morrison, <em>JACM</em>, 1968；Fredkin, <em>CACM</em>, 1960。</li></ul>',7))])}const P=A(p,[["render",m]]);export{f as __pageData,P as default};
